/**
 * Tokenize subcontent.
 *
 * @param {Array<Event>} events
 *   List of events.
 * @returns {boolean}
 *   Whether subtokens were found.
 */
export function subtokenize(
  events: Array<import('https://esm.sh/micromark-util-types@1.1.0/index.d.ts').Event>
): boolean
export type Chunk = import('https://esm.sh/micromark-util-types@1.1.0/index.d.ts').Chunk
export type Event = import('https://esm.sh/micromark-util-types@1.1.0/index.d.ts').Event
export type Token = import('https://esm.sh/micromark-util-types@1.1.0/index.d.ts').Token
